INSERT INTO `policy_pages` (`id`, `slug`, `title`, `content`, `status`, `last_updated`, `updated_by`, `created_at`) VALUES
(1, 'terms', 'Terms & Conditions', 'Welcome to Mama Bazar. By accessing or using our services, you agree to be bound by these terms.', 'published', 1790187895, NULL, '2026-09-23 18:24:55'),
(2, 'privacy-policy', 'Privacy Policy', 'Your privacy is important to us. We handle your personal data with utmost security and respect.', 'published', 1790187895, NULL, '2026-09-23 18:24:55'),
(3, 'return-refund', 'Return & Refund Policy', 'Products can be returned within 7 days of receipt in original, unused condition.', 'published', 1790187895, NULL, '2026-09-23 18:24:55'),
(4, 'shipping-policy', 'Shipping Policy', 'We deliver across Bangladesh. Delivery within Dhaka takes 24-48 hours, outside Dhaka 3-5 business days.', 'published', 1790187895, NULL, '2026-09-23 18:24:55');
